/* @author MILO-GAO(高振銘)@2020 */ package page2020.flow;import java.util.ArrayList;import java.util.LinkedHashMap;import java.util.List;import java.util.Map;import java.util.Set;import java.util.UUID;import javax.servlet.http.HttpSession;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.ui.Model;import page2020.Data;import page2020.core.App;import page2020.core.DataTable;import page2020.core.Flow;import page2020.core.Form;import page2020.core.Log;import page2020.core.Page;import page2020.core.Result;import page2020.core.Table;import page2020.data.DataWriter;import page2020.data.TableData;import page2020.unit.Ualert;import page2020.util.EmptyUtil;import page2020.view.B4;import page2020.view.Child;import page2020.view.Content;import page2020.view.Element;import page2020.view.Tag;import page2020.view.bs4.B4checkbox;import page2020.view.bs4.B4datalist;import page2020.view.bs4.B4element;import page2020.view.bs4.B4input;import page2020.view.bs4.B4radio;import page2020.view.bs4.B4select;import page2020.view.bs4.B4switch;import page2020.view.bs4.B4textarea;public class DataFlow extends Flow {	private static Logger log = LoggerFactory.getLogger(DataFlow.class);	protected Map<String, Child> forms = new LinkedHashMap<String, Child>();	protected Map<String, Child> tables = new LinkedHashMap<String, Child>();	private Map<String, B4datalist> datalists = new LinkedHashMap<String, B4datalist>();	public void data(Data data, Page page, Model model, HttpSession session) {		this.search(page, false);		if (data.count() > 0) {			data.getData().forEach((name, items) -> {				List<Content<?>> contents = page.findAll(name);				for (Content<?> c : contents) {					if (c instanceof B4select) {						((B4select) c).items(items);						if (Log.data) {							log.info("data: Control('" + name + "') <select> " + items.toString()); 						}											} else if (c instanceof B4checkbox) {						((B4checkbox) c).items(items);						if (Log.data) {							log.info("data: Control('" + name + "') <checkbox> " + items.toString()); 						}											} else if (c instanceof B4radio) {						((B4radio) c).items(items);						if (Log.data) {							log.info("data: Control('" + name + "')  <radio> " + items.toString()); 						}					}				}			});		}		if (data.count() > 0) {			data.getData().forEach((name, items) -> {				Content<?> c = page.find(name, "datalist", null);				if (c != null && c instanceof B4datalist) {					((B4datalist) c).values(items);					if (Log.data) {						log.info("data: DataList('" + name + "') " + items.toString());					}										}			});		}		if (! data.getFormBeanMap().isEmpty()) {			for (String name : data.getFormBeanMap().keySet()) {				Content<?> c = page.find(name, "form", null);				if (c != null && c instanceof Form) {					Form form = (Form) c;					if (form.getProp() != null && form.isJsp()) {						form.data(data.getFormBeanMap().get(name), model);						if (Log.data) {							log.info("data: Form('" + name + "') model='" + form.getModelAttribute() + "'");						}					}									}			}		}		if (data.getTableBeanMap().size() > 0) {			for (String name : data.getTableBeanMap().keySet()) {				Content<?> c = page.find(name, "table", null);				if (c != null && c instanceof Table) {					Table table = (Table) c;					if (table.getProp() != null) {						TableData tableData = this.tableData(table, data.getTableBeanMap().get(name), data, page.getApp(), session);						if (Log.data) {							log.info("data: Table('" + name + "') length=" + tableData.getLength());						}					}									}			}		}		if (! data.getDisableCtrlSet().isEmpty()) {			this.disabled(page, data.getDisableCtrlSet());		}	}	public B4element element(Result result, Data data, Element<?, ?> top, App app, Model model, HttpSession session) {		B4element element = B4.element();		if (result != null) {			Form form = (Form) top.find(result.getName(), "form", null);			if (form != null && form.getProp() != null) {				result.automate(form.getCode());				if (result.getStatus() == Result.success) {					form.complete();				}				element.append(new Ualert(result));				if (Log.data) {					log.info("element: Result('" + result.getName() + "') code=" + form.getCode()						+ ", status=" + result.getStatus());				}			}		}		if (data != null) {			if (data.getFormClzSet().size() > 0) {				data.getFormClzSet().forEach(name -> {					Content<?> content = top.find(name, "form", null);					if (content != null) {						element.append(content);						if (Log.data) {							log.info("element: Form('" + content.getName() + "')");						}					}				});			}			if (data.getFormBeanMap().size() > 0) {				data.getFormBeanMap().forEach((name, bean) -> {					Form form = (Form) top.find(name, "form", null);					if (form != null && form.getProp() != null) {						form.data(bean, model);						element.append(form);						if (Log.data) {							log.info("element: Form('" + form.getName() + "') model='" + form.getModelAttribute() + "'");						}					}				});			}			if (data.getTableClzSet().size() > 0) {				data.getFormClzSet().forEach(name -> {					Content<?> content = top.find(name, "table", null);					if (content != null) {						element.append(content);						if (Log.data) {							log.info("element: Table('" + content.getName() + "')");						}					}				});			}			if (data.getTableBeanMap().size() > 0) {				data.getTableBeanMap().forEach((name, list) -> {					Table table = (Table) top.find(name, "table", null);					if (table != null && table.getProp() != null) {						TableData tableData = this.tableData(table, list, data, app, session);						element.append(table);						if (Log.data) {							log.info("element: Table('" + table.getName() + "') length=" + tableData.getLength());						}					}				});			}			if (! data.getDisableCtrlSet().isEmpty()) {				this.disabled(page, data.getDisableCtrlSet());			}		}		element.build();		if (Log.data) {			log.info("element: " + element.count());		}		return element;	}	public TableData process(List<?> source, String name, Page page, Data data, HttpSession session) {		Table table = (Table) page.find(name, "table", null);		if (table != null && table.isDatatableJS()) {			DataTable argument = table.getDatatable();			if (argument.isProcess()) {				TableData tableData = this.tableData(table, source, data, page.getApp(), session);								if (! argument.isServer()) {					return tableData;					}			}		}		return new TableData();	}	public List<String> proxy(List<?> source, String name, Page page, Data data, HttpSession session) {		Table table = (Table) page.find(name, "table", null);		if (table != null && table.isDatatableJS()) {			DataTable argument = table.getDatatable();			if (argument.isProxy()) {				TableData tableData = this.tableData(table, source, data, page.getApp(), session);								if (! argument.isServer()) {					List<String> array = new ArrayList<String>();					int length = argument.getProxyLength();					if (length == 0) {						String uuid = UUID.randomUUID().toString();						array.add(uuid);						session.setAttribute(uuid, tableData);					} else {						int pos = 0;						do {							String uuid = UUID.randomUUID().toString();							array.add(uuid);							session.setAttribute(uuid, tableData.copy(pos, length));							pos += length;						} while ((pos + 1) < tableData.getLength());					}					return array;					}			}		}		return new ArrayList<String>();	}	@Override	public Flow automate() {		super.automate();		if (! super.view.getFormClasses().isEmpty()) {			super.view.getFormClasses().forEach(clazz -> super.view.append(new Form(clazz)));			super.view.getFormClasses().clear();		}		if (! super.view.getTableClasses().isEmpty()) {			super.view.getTableClasses().forEach(clazz -> super.view.append(new Table(clazz)));			super.view.getTableClasses().clear();		}		this.search(super.view, true);		if (! this.datalists.isEmpty()) {						for (String key : this.datalists.keySet()) {				B4datalist datalist = this.datalists.get(key);				if (App.hasItemKey(datalist.getName())) {					datalist.code(App.itemValue(datalist.getName()));				}				super.view.append(datalist);			}			super.page.getScripts().add(Path.page2020 + "datalist.js");		}		super.page.getScripts().add(Path.page2020 + "control.js");		if (Log.flow) {			StringBuilder sb1 = new StringBuilder().append(super.logName);			if (! this.forms.isEmpty()) {				sb1.append("Form(" + this.forms.keySet().toString() + ") ");			}			if (! this.tables.isEmpty()) {				sb1.append("Table(" + this.tables.keySet().toString() + ")");			}			log.info(sb1.toString());		}		return this;	}	protected void insert(Element<?, ?> element, int index, Tag<?> tag) {		this.forms.forEach((key, child) -> {			if (element == child.getElement()) {				int i = child.getIndex();				if (i >= index) {					child.setIndex(i + 1);					if (i == index) {						element.add(index, tag);					}				}			}		});		this.tables.forEach((key, child) -> {			if (element == child.getElement()) {				int i = child.getIndex();				if (i >= index) {					child.setIndex(i + 1);					if (i == index) {						element.add(index, tag);					}				}			}		});	}	private void search(Element<?, ?> element, boolean automate) {		int count = element.count();		for (int i=0; i < count; i++) {			Content<?> c = element.get(i);			if (c instanceof Form) {				Form form = (Form) c;				if (form.getProp() != null) {					if (automate) {						form.automate(super.code);						if (! form.getDatalists().isEmpty()) {							this.datalist(form);						}					}					@SuppressWarnings("unchecked")					Child child = new Child((Element<?, Content<?>>) element, i, form);					this.forms.put(form.getName(), child);				}			} else if (c instanceof Table) {				Table table = (Table) c;				if (table.getProp() != null) {					if (automate) {						table.automate(super.ui, super.code);						if (! table.getDatalists().isEmpty()) {							this.datalist(table);						}						if (table.getView().getSelector().count() > 0) {							super.page.getSelector().merge(table.getView().getSelector());						}					}					@SuppressWarnings("unchecked")					Child child = new Child((Element<?, Content<?>>) element, i, table);					this.tables.put(table.getName(), child);				}			} else if (c instanceof Element<?, ?>) {				Element<?, ?> child = (Element<?, ?>) c;				if (child.count() > 0) {					this.search(child, automate);				}			}		}			}	private void datalist(Form form) {		while (! form.getDatalists().isEmpty()) {			B4datalist datalist = form.getDatalists().remove(0);			if (! this.datalists.containsKey(datalist.getName())) {				this.datalists.put(datalist.getName(), datalist);			}		}	}	private void datalist(Table table) {		while (! table.getDatalists().isEmpty()) {			B4datalist datalist = table.getDatalists().remove(0);			if (! this.datalists.containsKey(datalist.getName())) {				this.datalists.put(datalist.getName(), datalist);			}		}	}	private TableData tableData(Table table, List<?> source, Data data, App app, HttpSession session) {		if (EmptyUtil.not(source)) {			TableData tableData = table.data(source, data);			if (table.isSave() && session != null) {				String userid = (String) session.getAttribute(SysKey.userid);				DataWriter.write(tableData.document(userid, app.getName(), table.isSerial()));			}			return tableData;		}		return new TableData();			}	private void disabled(Page page, Set<String> set) {		set.forEach(name -> {			Content<?> c = page.find(name);			if (c != null) {				if (c instanceof B4input) {					((B4input) c).disabled(true);				} else if (c instanceof B4select) {					((B4select) c).disabled(true);				} else if (c instanceof B4textarea) {					((B4textarea) c).disabled(true);				} else if (c instanceof B4checkbox) {					((B4checkbox) c).disabled(true);				} else if (c instanceof B4radio) {					((B4radio) c).disabled(true);				} else if (c instanceof B4switch) {					((B4switch) c).disabled(true);				}			}		});	}}